    #include <iostream>
#include <queue>
#include <vector>
using namespace std;

class Node
{
  public:
    int data;
    Node *left, *right;
    Node(int x)
    {
        data = x;
        left = right = nullptr;
    }
};

// Function to store the preorder
void serializePreOrder(Node *root, vector<int> &arr)
{

    // Push -1 if root is null.
    if (root == nullptr)
    {
        arr.push_back(-1);
        return;
    }

    // Push the root into result.
    arr.push_back(root->data);
    serializePreOrder(root->left, arr);
    serializePreOrder(root->right, arr);
}

// Main function to serialize a tree.
vector<int> serialize(Node *root)
{
    vector<int> arr;
    serializePreOrder(root, arr);
    return arr;
}

// Function to restore the array from preorder
Node *deserializePreOrder(int &i, vector<int> &arr)
{

    // if element is -1 return null
    if (arr[i] == -1)
    {
        i++;
        return nullptr;
    }

    // Create the root node.
    Node *root = new Node(arr[i]);
    i++;

    // Create the left and right subtree.
    root->left = deserializePreOrder(i, arr);
    root->right = deserializePreOrder(i, arr);

    return root;
}

Node *deSerialize(vector<int> &arr)
{
    int i = 0;
    return deserializePreOrder(i, arr);
}

// Function to print preorder traversal
void preorder(Node *root)
{
    if (root == nullptr)
        return;

    cout << root->data << " ";
    preorder(root->left);
    preorder(root->right);
}

int main()
{
    //       10
    //     /    \
    //    20    30
    //  /   \
    // 40   60

    Node *root = new Node(10);
    root->left = new Node(20);
    root->right = new Node(30);
    root->left->left = new Node(40);
    root->left->right = new Node(60);

    // Serialize the original tree
    vector<int> arr = serialize(root);

    // Deserialize the tree
    Node *res = deSerialize(arr);

    // Print the deserialized tree in level order
    cout << "[";
    queue<Node *> q;
    q.push(res);
    bool first = true;

    while (!q.empty())
    {
        Node *curr = q.front();
        q.pop();

        if (curr == nullptr)
            continue;

        if (!first)
            cout << ", ";

        cout << curr->data;
        first = false;

        q.push(curr->left);
        q.push(curr->right);
    }

    cout << "]" << endl;

    return 0;
}


