function deSerialize(arr)
{
    if (arr[0] === -1) {
        return null;
    }

    // create root node and push
    // it into queue
    let root = new Node(arr[0]);
    let q = [ root ];

    let i = 1;
    while (q.length > 0) {
        let curr = q.shift();

        // If left node is not null
        if (arr[i] !== -1) {
            let left = new Node(arr[i]);
            curr.left = left;
            q.push(left);
        }
        i++;

        // If right node is not null
        if (arr[i] !== -1) {
            let right = new Node(arr[i]);
            curr.right = right;
            q.push(right);
        }
        i++;
    }

    return root;
}

// Function to print preorder traversal
function preorder(root)
{
    if (root === null) {
        return;
    }

    console.log(root.data + " ");
    preorder(root.left);
    preorder(root.right);
}

